import os, glob, re

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    content = open(session_file).read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in content[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Keys found:", sorted(G.keys()))
for k in sorted(G.keys()):
    print(f"\n{k} input ({len(G[k][0])}x{len(G[k])}):")
    for row in G[k]:
        print(row)

